#!/usr/bin/env bash
# bench.sh — GuideLLM sweep over the endpoint-alive general-chat model set.
#
# Data-driven: reads bench/models-bench.json (models, provider backends,
# NIM-ID -> HF tokenizer map) and bench/scenarios/ (generated by
# scripts/gen-scenarios.py from models-bench.json + context-map.json).
#
# The tokenizer fix: GuideLLM used to treat the NIM model id as a
# HuggingFace repo and die. Every run now passes an explicit
# --tokenizer kind=huggingface_auto,model=<hf-repo> from models-bench.json.
# Models whose tokenizer is not verified are skipped unless
# --include-provisional is given.
#
# Usage:
#   ./bench.sh [--all] [--list] [--dry-run] [--include-provisional] [--long]
#              [--provider nvidia|mistral|gemini|openrouter|herd] [filter]
#
#   no args            same as --all
#   --all              benchmark every eligible general-chat model
#   --list             print the eligible model list and exit
#   --dry-run          print the guidellm commands without running them
#                      (does not require provider API keys)
#   --include-provisional
#                      also run models with provisional/unverified tokenizers
#   --long             use the long-context scenario variant (8k prompt /
#                      1k output) where one was generated (models with
#                      effective context >= 128k)
#   --provider P       only models on provider P
#   filter             only models whose id contains the substring
#
# Provider keys come from the environment (see bench/models-bench.json
# "providers" for the variable names):
#   set -a; . ~/.secrets; set +a; ./bench.sh --all
set -u
DIR="$(cd "$(dirname "$0")" && pwd)"
BENCH_DIR="$DIR/bench"
MODELS_JSON="$BENCH_DIR/models-bench.json"
SCEN_DIR="$BENCH_DIR/scenarios"
OUT="${OUT:-$HOME/.local/share/nvidia-alive/bench}"

ALL=0; LIST=0; DRYRUN=0; PROV=0; LONG=0; PROVIDER=""; FILTER=""

while [ $# -gt 0 ]; do
  case "$1" in
    --all) ALL=1 ;;
    --list) LIST=1 ;;
    --dry-run) DRYRUN=1 ;;
    --include-provisional) PROV=1 ;;
    --long) LONG=1 ;;
    --provider) PROVIDER="${2:-}"; shift ;;
    --provider=*) PROVIDER="${1#--provider=}" ;;
    -h|--help) sed -n '2,30p' "$0"; exit 0 ;;
    --*) echo "unknown flag: $1" >&2; exit 2 ;;
    *) FILTER="$1" ;;
  esac
  shift
done
[ "$ALL" -eq 0 ] && [ "$LIST" -eq 0 ] && [ -z "$FILTER" ] && [ -z "$PROVIDER" ] && ALL=1

if [ ! -f "$MODELS_JSON" ]; then
  echo "models file missing: $MODELS_JSON" >&2; exit 2
fi
command -v python3 >/dev/null || { echo "python3 required" >&2; exit 2; }

# Regenerate per-model scenarios (cheap; keeps them in sync with
# models-bench.json and context-map.json when it lands).
python3 "$DIR/scripts/gen-scenarios.py" >&2 || exit 2

# Emit: provider\x1fmodel_id\x1ftokenizer\x1fverified(0/1)\x1fkey_env\x1ftarget\x1fvalidate\x1frequest_path\x1fstrict_compat(0/1)\x1ftokenizer_load_kwargs(pairs)
model_rows() {
  python3 - "$MODELS_JSON" <<'EOF'
import json, sys
bench = json.load(open(sys.argv[1]))
def yaml_bool(v):
    return "true" if v is True else "false" if v is False else str(v)
for m in bench["models"]:
    p = bench["providers"][m["provider"]]
    tlk = m.get("tokenizer_load_kwargs") or {}
    pairs = ",".join(f"load_kwargs.{k}={yaml_bool(v)}" for k, v in tlk.items())
    print("\x1f".join([
        m["provider"], m["id"],
        m.get("tokenizer") or "",
        "1" if m.get("tokenizer_verified") else "0",
        p.get("key_env") or "",
        p["target"],
        p.get("validate") or "",
        p.get("request_path") or "/v1/chat/completions",
        "1" if p.get("strict_compat") else "0",
        pairs,
    ]))
EOF
}

selected=0; ran=0; failed=0; skipped_key=0; skipped_tok=0
# NOTE: \x1f (unit separator) is the field delimiter, NOT tab: tab is IFS
# whitespace, so read would collapse consecutive tabs and swallow empty
# fields (this silently broke keyless providers like herd).
while IFS="$(printf '\x1f')" read -r provider model tokenizer verified key_env target validate request_path strict_compat tok_load_kwargs; do
  [ -z "$model" ] && continue
  if [ -n "$PROVIDER" ] && [ "$provider" != "$PROVIDER" ]; then continue; fi
  if [ -n "$FILTER" ]; then
    case "$model" in *"$FILTER"*) ;; *) continue ;; esac
  fi
  if [ "$verified" != "1" ] && [ "$PROV" -eq 0 ]; then
    echo "SKIP (provisional tokenizer): $model"
    skipped_tok=$((skipped_tok + 1)); continue
  fi
  if [ -z "$tokenizer" ]; then
    echo "SKIP (no tokenizer): $model"
    skipped_tok=$((skipped_tok + 1)); continue
  fi
  selected=$((selected + 1))
  if [ "$LIST" -eq 1 ]; then
    printf '%s  %s  tok=%s%s\n' "$provider" "$model" "$tokenizer" \
      "$([ "$verified" = "1" ] || echo ' (provisional)')"
    continue
  fi
  key=""
  if [ -n "$key_env" ]; then
    key="${!key_env:-}"
    if [ -z "$key" ] && [ "$DRYRUN" -eq 0 ]; then
      echo "SKIP (no $key_env in env): $model"
      skipped_key=$((skipped_key + 1)); continue
    fi
  fi

  _slug="${model//\//__}"; _slug="${_slug//:/__}"
  if [ "$LONG" -eq 1 ]; then
    scen="$SCEN_DIR/${_slug}-long.json"
    if [ ! -f "$scen" ]; then
      echo "SKIP (no long-context variant): $model"
      continue
    fi
  else
    scen="$SCEN_DIR/${_slug}.json"
  fi
  safe="$_slug"
  if [ ! -f "$scen" ]; then
    echo "SKIP (scenario missing): $model" >&2; failed=$((failed + 1)); continue
  fi

  tokenizer_spec="kind=huggingface_auto,model=$tokenizer"
  if [ -n "$tok_load_kwargs" ]; then
    tokenizer_spec="$tokenizer_spec,$tok_load_kwargs"
  fi
  backend="kind=openai_http,target=$target,model=$model,request_format=$request_path"
  if [ "$strict_compat" = "1" ]; then
    backend="$backend,openai_strict_compat=true"
  fi
  if [ -n "$validate" ]; then
    backend="$backend,validate_backend=$validate"
  fi
  if [ -n "$key" ]; then
    backend="$backend,api_key=$key"
  fi
  cmd=(guidellm run --config "$scen"
    --backend "$backend"
    --tokenizer "$tokenizer_spec"
    --output "kind=json,path=$OUT/${provider}__${safe}.json"
    --disable-console-interactive)

  echo "=== [$provider] $model"
  if [ "$DRYRUN" -eq 1 ]; then
    # redact credential material from the displayed command (exec uses the
    # unredacted ${cmd[@]} below)
    redacted=()
    for arg in "${cmd[@]}"; do
      case "$arg" in
        *api_key=*) redacted+=("${arg%%api_key=*}api_key=<redacted>") ;;
        *) redacted+=("$arg") ;;
      esac
    done
    printf '%q ' "${redacted[@]}"; echo
    ran=$((ran + 1)); continue
  fi
  mkdir -p "$OUT"
  if "${cmd[@]}"; then
    ran=$((ran + 1))
  else
    echo "FAILED: $model" >&2
    failed=$((failed + 1))
  fi
done <<EOF
$(model_rows)
EOF

if [ "$LIST" -eq 1 ]; then
  echo "listed $selected models"
else
  echo "done: ran=$ran failed=$failed skipped_no_key=$skipped_key skipped_tokenizer=$skipped_tok -> $OUT"
fi
